def wildcard_match(pattern: str, text: str) -> bool:
    # dp[i][j] is True if pattern[:i] matches text[:j]
    m, n = len(pattern), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns starting with '*': they can match an empty prefix
    for i in range(1, m + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]
        else:
            break

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            p = pattern[i - 1]
            if p == '*':
                # '*' matches zero chars: dp[i-1][j]
                # or '*' matches at least one char: dp[i][j-1]
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif p == '?' or p == text[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            # else remains False

    return dp[m][n]
